action.command:
cd /workspace && ls 01-frontend/shell/.env.deployment 2>&1; node -e "
const fs=require('fs');
const ws=['shared','shell','mfe-fp','mfe-kp','mfe-mp','mfe-verwaltungsakt','mfe-vp','mfe-ws','mfe1','mfe-ewm'];
const missing=[];
for (const w of ws) { try{ JSON.parse(fs.readFileSync('01-frontend/'+w+'/package.json')); }catch(e){ missing.push(w+': '+e.message); } }
console.log(missing.length? 'BAD: '+JSON.stringify(missing): 'all workspace package.json valid');
const l=JSON.parse(fs.readFileSync('01-frontend/package-lock.json','utf8'));
console.log('lockfileVersion:', l.lockfileVersion, 'has @hey-api/openapi-ts:', JSON.stringify(Object.keys(l.packages||{}).filter(k=>k.includes('hey-api')).slice(0,5)));
"

